import{_ as s,o as a,c as n,a as o}from"./app.83c7065c.js";const F=JSON.parse('{"title":"node开发遇到的一个小坑","description":"","frontmatter":{"title":"node开发遇到的一个小坑","date":"2019-09-03"},"headers":[],"relativePath":"2019/node-dev-gotcha.md","lastUpdated":1786184870000}'),e={name:"2019/node-dev-gotcha.md"},p=o(`<h3 id="写在前面" tabindex="-1">写在前面 <a class="header-anchor" href="#写在前面" aria-hidden="true">#</a></h3><p>大前端之路又迈出了坚实一步。</p><p>leader架不住我们前端切图仔的各种游说，终于决定了上node。马上就可以写node接入层了，后端哥们可以专心开发微服务，切图仔们也可以想要什么数据字段就用什么了，毕竟求人不如求己。</p><p>leader给我分配了搭建框架的任务，以公司内部koa2+vue框架为基础，自己改改应该就可以了。毕竟只是个管理后台，做成MPA方便编译、迁移和维护。SPA页面数量过多，热更新直接爆内存堆，之前体会过一次，不想再碰。</p><h3 id="踩坑记录" tabindex="-1">踩坑记录 <a class="header-anchor" href="#踩坑记录" aria-hidden="true">#</a></h3><p>搭框架自然要区分各种运行环境，开发、测试、生产自然是标配。界面上会根据环境不同给一些信息提示，在node里很自然就要写这样的语句<code>env = p<wbr>rocess.env.NODE_ENV</code>来判断当前所处的环境。</p><p>用的现成框架，却在EJS条件渲染视图文件的时候总是失败，始终没有触发到我想要的逻辑分支。看了几分钟，开始看页面env变量的值。</p><p>结果居然发现框架里是这么写的</p><div class="language-javascript"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#C792EA;">const</span><span style="color:#A6ACCD;"> env </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> JSON</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">stringify</span><span style="color:#A6ACCD;">(process</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">env</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">NODE_ENV </span><span style="color:#89DDFF;">||</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">development</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">)</span></span>
<span class="line"></span></code></pre></div><p>而我的模板条件渲染语句是这么写的</p><div class="language-javascript"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#89DDFF;">&lt;%</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;font-style:italic;">if</span><span style="color:#A6ACCD;">(env</span><span style="color:#89DDFF;">==</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">development</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">) </span><span style="color:#89DDFF;">{%&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">    </span><span style="color:#676E95;font-style:italic;">//do something </span></span>
<span class="line"><span style="color:#89DDFF;">&lt;%</span><span style="color:#F07178;"> </span><span style="color:#89DDFF;">}</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">%&gt;</span></span>
<span class="line"></span></code></pre></div><p>打印一看，当然不能进入分支逻辑</p><div class="language-javascript"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#C792EA;">var</span><span style="color:#A6ACCD;"> a </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> JSON</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">stringify</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">development</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// &#39;&quot;development&quot;&#39;</span></span>
<span class="line"><span style="color:#C792EA;">var</span><span style="color:#A6ACCD;"> b </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">development</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// &#39;development&#39;</span></span>
<span class="line"><span style="color:#A6ACCD;">a </span><span style="color:#89DDFF;">==</span><span style="color:#A6ACCD;"> b</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// false</span></span>
<span class="line"><span style="color:#A6ACCD;">a </span><span style="color:#89DDFF;">===</span><span style="color:#A6ACCD;"> b</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// false</span></span>
<span class="line"></span></code></pre></div><p>框架大佬多此一举用了<code>JSON.stringify</code>，把字符串<code>&#39;development&#39;</code>变成了有额外双引号的字符串<code>&#39;&quot;development&quot;&#39;</code>，二者的比较自然变成了<code>development</code>和<code>development+双引号</code>的比较，永远不会相等，不管使用<code>严格相等===</code>还是<code>转换类型相等==</code></p><p><strong>踩坑记录完毕</strong></p>`,15),l=[p];function t(c,r,D,y,d,i){return a(),n("div",null,l)}const A=s(e,[["render",t]]);export{F as __pageData,A as default};
